/bin/bash -lc "python3 - <<'PY'
import subprocess,glob,re,os
base='<HOME>'
for f in sorted(glob.glob(base+'/*.pdf')):
 try: txt=subprocess.check_output(['pdftotext','-layout',f,'-'],stderr=subprocess.DEVNULL).decode('utf8','ignore')
 except Exception as e: print(os.path.basename(f),'EXTRACT_FAIL'); continue
 # normalize lines, identify section headings (numbered short lines)
 lines=[re.sub(r'\\s+',' ',x).strip() for x in txt.splitlines()]
 heads=[]
 for x in lines:
  if re.match(r'"'^'"\\d+(?:\\.\\d+)*\\s+[A-Z][A-Za-z]',x) and len(x)<100 and not re.search(r'\\b(19|20)\\d{2}\\b',x): heads.append(x)
 # first sentence after Introduction occurrence
 m=re.search(r'\\b(?:INTRODUCTION|Introduction)\\b',txt)
 sn=''
 if m:
  frag=re.sub(r'\\s+',' ',txt[m.end():m.end()+1200])
  ss=re.split(r'(?<=[."'!?])'"\\s+',frag)
  for s in ss:
   s=s.strip()
   if len(s)>50:
    sn=s[:240]; break
 print(os.path.basename(f),'heads=',heads[:12],'intro=',sn)
PY"

